// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz: _baseToken and _feeRate and other params
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // keep feeRate in admissible range
        if (_feeRate > type(uint16).max) return; // redundant but harmless
        vm.assume(_feeRate <= 5000);

        // We call initialize as the caller (msg.sender). No special actor setup needed.
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // If initialize reverted (e.g., already initialized or feeRate check) then we cannot assert equality of baseToken with _baseToken
        // The universal property: whenever initialize succeeds, c.baseToken() equals the supplied _baseToken.
        if (ok) {
            assertTrue(c.baseToken() == _baseToken);
        }
    }
}

