pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // General rule: after calling initialize(...), the contract's baseToken getter returns exactly the _baseToken argument passed.
    // The mutant sets baseToken = _nft instead, so for many choices (where _baseToken != _nft) the mutant will violate this.
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // Keep fuzz domain wide but avoid obviously invalid feeRate > 5000 for the valid path
        if (_feeRate > 5000) _feeRate = 5000;

        // Ensure not already initialized
        // Call initialize with fuzzed parameters and observe baseToken getter
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            // If initialize reverts (shouldn't on reference for these inputs except AlreadyInitialized/feeRate) treat as failure
            ok = false;
        }

        // The universal property: if initialize succeeds, then baseToken() == _baseToken.
        // We assert this property (the reference satisfies it for all inputs; the mutant will fail for some inputs where _baseToken != _nft).
        if (ok) {
            assertTrue(c.baseToken() == _baseToken, "baseToken must equal the provided _baseToken");
        } else {
            // If initialize reverted, assert that it was due to feeRate > 5000 or AlreadyInitialized; we avoided AlreadyInitialized by fresh deploy
            // and clamped feeRate, so this branch should not execute under normal fuzz inputs — still, assert false to flag unexpected revert.
            assertTrue(false, "initialize reverted unexpectedly");
        }
    }
}

